windowclass.script:
function updateFonts()
	local nTier = math.floor(armor_tier.getValue());
	local bRigid = is_rigid.getValue() == 1;
	local sFont = bRigid and "sheetlabelbold" or "sheetlabel";

	-- av_b and av_f: Always black (FF000000)
	-- User said "no modifications", so we'll stick to sheetlabel for these
	av_b.setFont("sheetlabel");
	av_b.setColor("FF000000");
	av_f.setFont("sheetlabel");
	av_f.setColor("FF000000");

	-- av_e and av_p: White (FFFFFFFF) only for Plate (Tier 3)
	local sColor = (nTier == 3) and "FFFFFFFF" or "FF000000";
	av_e.setFont(sFont);
	av_e.setColor(sColor);
	av_p.setFont(sFont);
	av_p.setColor(sColor);
end

stringfield.script:
function onValueChanged()
	window.updateFonts();
	-- Recalculate Area Attack if armor values change
	local nodeChar = window.getDatabaseNode().getParent().getParent();
	if ArmorManager and ArmorManager.calculateAreaAttack then
		ArmorManager.calculateAreaAttack(nodeChar);
	end
end

numberfield.script:
function onInit()
	onValueChanged();
end
function onValueChanged()
	local nTier = getValue();
	if nTier == 1 then
		window.armor_bg_e.setIcon("rigid1");
		window.armor_bg_p.setIcon("rigid1");
		window.armor_bg_e.setVisible(true);
		window.armor_bg_p.setVisible(true);
	elseif nTier == 2 then
		window.armor_bg_e.setIcon("rigid2");
		window.armor_bg_p.setIcon("rigid2");
		window.armor_bg_e.setVisible(true);
		window.armor_bg_p.setVisible(true);
	elseif nTier == 3 then
		window.armor_bg_e.setIcon("rigid3");
		window.armor_bg_p.setIcon("rigid3");
		window.armor_bg_e.setVisible(true);
		window.armor_bg_p.setVisible(true);
	else
		window.armor_bg_e.setVisible(false);
		window.armor_bg_p.setVisible(false);
	end
	window.updateFonts();
end

genericcontrol.script:
local ICON_DATA = { ["SK"] = { shk = "shk5", bld = "bld1" }, ["FA"] = { shk = "shk4", bld = "bld2" }, ["NK"] = { shk = "shk5", bld = "bld3", amp = "amp1" }, ["SH"] = { shk = "shk3", bld = "bld2" }, ["UA"] = { shk = "shk1", bld = "bld1", amp = "amp2" }, ["EL"] = { shk = "shk2", bld = "bld1", amp = "amp2" }, ["FO"] = { shk = "shk1", bld = "bld1", amp = "amp2" }, ["HA"] = { shk = "shk2", amp = "amp3" }, ["TX"] = { shk = "shk4", bld = "bld2" }, ["AB"] = { shk = "shk4", bld = "bld3" }, ["PV"] = { shk = "shk4", bld = "bld2" }, ["TH"] = { shk = "shk3", bld = "bld2", amp = "amp1" }, ["KN"] = { shk = "shk2", bld = "bld1", amp = "amp2" }, ["CA"] = { shk = "shk1", bld = "bld1", amp = "amp2" }, ["FO"] = { shk = "shk2", amp = "amp2" }, };
function onInit() local sLoc = DB.getValue(window.getDatabaseNode(), "location", ""); local tData = ICON_DATA[sLoc]; if not tData then return; end
-- SHK always centered in this control addBitmapWidget(tData.shk);
-- BLD in left control if tData.bld then window.icon_bld.addBitmapWidget(tData.bld); end
-- AMP in right control if tData.amp then window.icon_amp.addBitmapWidget(tData.amp); end end

windowclass.script:
local _nLastApplied = 0;

function onInit()
	_nLastApplied = tonumber(level.getValue()) or 0;
	updateHeal();
end

function applyImpairment()
	local nLevel = tonumber(level.getValue()) or 0;
	local nDelta = nLevel - _nLastApplied;

	if nDelta ~= 0 and HarnManager and HarnManager.addImpairment then
		local nodeEntry = getDatabaseNode();
		if nodeEntry then
			local sLocation = location.getValue();
			local sSide = side.getValue();
			local nodeChar = nodeEntry.getParent().getParent();

			if nodeChar and sLocation ~= "" then
				local nValueToAdd = nDelta * 5;
				Debug.chat("Injury update: " .. sLocation .. " (Level " .. nLevel .. "), adding " .. nValueToAdd .. " to zone.");
				HarnManager.addImpairment(nodeChar, sLocation, sSide, nValueToAdd);
				_nLastApplied = nLevel;
			end
		end
	end
end

function updateHeal()
	local nodeEntry = getDatabaseNode();
	if not nodeEntry then return end

	local nInjuryHR = DB.getValue(nodeEntry, "injury_hr", 0);
	local nodeChar = nodeEntry.getParent().getParent();
	local nHB = 0;
	if nodeChar then
		nHB = DB.getValue(nodeChar, "healing_base", 0);
	end

	local nHeal = nInjuryHR * nHB;
	heal.setValue(nHeal);
end

stringfield.script:
function onInit()
	local sSev = window.severity.getValue();
	local sLvl = window.level.getValue();
	local sAsp = window.aspect.getValue();
	if sSev ~= "" or sLvl ~= "" or sAsp ~= "" then
		setValue(sSev .. sLvl .. sAsp);
	end
end
function onLoseFocus()
	local sVal = getValue();
	if #sVal == 3 then
		local sSev = sVal:sub(1,1):upper();
		local sLvl = sVal:sub(2,2);
		local sAsp = sVal:sub(3,3):upper();

		window.severity.setValue(sSev);
		window.level.setValue(sLvl);
		window.aspect.setValue(sAsp);
		window.applyImpairment();
	end
end

buttoncontrol.script:
function onButtonPress()
	local node = window.getDatabaseNode();
	if node then
		local nLevel = tonumber(window.level.getValue()) or 0;
		if nLevel > 0 and HarnManager and HarnManager.addImpairment then
			local sLocation = DB.getValue(node, "location", "");
			local sSide = DB.getValue(node, "side", "-");
			local nodeChar = node.getParent().getParent();
			if nodeChar and sLocation ~= "" then
				HarnManager.addImpairment(nodeChar, sLocation, sSide, -nLevel * 5);
			end
		end
		node.delete();
	end
end

windowclass.script:
local _nLastApplied = 0;

function onInit()
	_nLastApplied = tonumber(level.getValue()) or 0;
	updateDeleteButton();
end

function updateDeleteButton()
	local bPerm = is_perm.getValue() == 1;
	idelete.setVisible(not bPerm);
end

function applyFatigueDelta()
	local nLevel = tonumber(level.getValue()) or 0;
	local nDelta = (nLevel - _nLastApplied) * 5;

	if nDelta ~= 0 and HarnManager and HarnManager.addWeaknessFatigue then
		local nodeChar = getDatabaseNode().getParent().getParent();
		if nodeChar then
			HarnManager.addWeaknessFatigue(nodeChar, nDelta);
			_nLastApplied = nLevel;
		end
	end
end

numberfield.script:
function onValueChanged()
	local nVal = getValue();
	if nVal < 0 then
		setValue(0);
		return;
	elseif nVal > 6 then
		setValue(6);
		return;
	end
	window.applyFatigueDelta();
end

buttoncontrol.script:
function onButtonPress()
	local nLevel = tonumber(window.level.getValue()) or 0;
	if nLevel > 0 and HarnManager and HarnManager.addWeaknessFatigue then
		local nodeChar = window.getDatabaseNode().getParent().getParent();
		if nodeChar then
			HarnManager.addWeaknessFatigue(nodeChar, -nLevel * 5);
		end
	end
	window.getDatabaseNode().delete();
end

windowclass.script:
function onInit()
	-- Initialize body locations
	local nodeChar = getDatabaseNode();
	if not nodeChar then return; end

	local nodeList = DB.createChild(nodeChar, "bodylocations");

	-- Consolidation Logic: If Hip or Groin exist, rename/merge them to Pelvis
	local nodePelvis = nil;
	local nodesToMerge = {};
	for _, node in pairs(nodeList.getChildren()) do
		local sLoc = DB.getValue(node, "location", ""):lower();
		if sLoc == "pelvis" then
			nodePelvis = node;
		elseif sLoc == "hip" or sLoc == "groin" then
			table.insert(nodesToMerge, node);
		end
	end

	if #nodesToMerge > 0 then
		if not nodePelvis then
			nodePelvis = nodesToMerge[1];
			DB.setValue(nodePelvis, "location", "string", "Pelvis");
			table.remove(nodesToMerge, 1);
		end
		-- Delete extras
		for _, node in ipairs(nodesToMerge) do
			node.delete();
		end
	end

	-- Standard Initialization
	if DB.getChildCount(nodeList) == 0 then
		local locations = {
			"SK", "FA", "NK", "SH", "UA",
			"EL", "FO", "HA", "TX", "AB",
			"PV", "TH", "KN", "CA", "FT"
		};
		for _, loc in ipairs(locations) do
			local node = DB.createChild(nodeList);
			DB.setValue(node, "location", "string", loc);
			DB.setValue(node, "av_b", "string", "0");
			DB.setValue(node, "av_e", "string", "0");
			DB.setValue(node, "av_p", "string", "0");
			DB.setValue(node, "av_f", "string", "0");
			DB.setValue(node, "is_rigid", "number", 0);
		end
	end

	-- Initial Body Location Update to populate ranges and restore icons
	if ArmorManager and ArmorManager.calculateArmor then
		ArmorManager.calculateArmor(nodeChar);
	end

	-- Initial Area Attack Calculation
	if ArmorManager and ArmorManager.calculateAreaAttack then
		ArmorManager.calculateAreaAttack(nodeChar);
	end
end

function updateShockUI()
	local nState = shock_state.getValue();
	shock_none_btn.setValue(nState == 0 and 1 or 0);
	shock_stn_btn.setValue(nState == 1 and 1 or 0);
	shock_inc_btn.setValue(nState == 2 and 1 or 0);
	shock_unc_btn.setValue(nState == 3 and 1 or 0);
	shock_kia_btn.setValue(nState == 4 and 1 or 0);
end

